using System.Text.Json.Nodes;
namespace Storage;

// Shared inbound receiver: Manufacturing finished goods or Logistics raw goods.
// The historical class/job key remains compatible with pending upgrade jobs.
// The receiver promises finite capacity; only a committed departure imports stock.
public static class FinishedCustody
{
    public sealed class Capacity(string message):Conflict(message);
    static void Complete(JsonObject value,params string[] fields){Rules.Fields(value,fields);if(fields.Any(f=>!value.ContainsKey(f)))throw new Validation("Complete finished custody object required");}
    static readonly Dictionary<string,JsonObject> Locations=JsonNode.Parse(File.ReadAllText(Path.Combine(AppContext.BaseDirectory,"handling-facility.json")))!["locations"]!.AsArray().Select(n=>n!.AsObject()).ToDictionary(n=>n["id"]!.ToString());
    static void Endpoint(JsonNode? value,string owner,string kind,string category){if(!Locations.TryGetValue(Rules.Text(value),out var p)||p["owner"]!.ToString()!=owner||p["kind"]!.ToString()!=kind||!p["compatible"]!.AsArray().Any(n=>n!.ToString()==category))throw new Conflict("Unknown or incompatible finished custody endpoint");}
    public static JsonObject Validate(JsonObject e){
        var h=e["payload"] as JsonObject??throw new Validation("Inbound custody object required");Complete(h,"id","run_id","epoch","source","destination_owner","origin","destination","state","unit","departure_token","receipt_id","reason");foreach(var key in new[]{"id","run_id","epoch"})Rules.Uuid(h[key]);
        var unit=h["unit"] as JsonObject??throw new Validation("Whole finished unit required");Complete(unit,"id","barcode","run_id","epoch","contents","category","state","owner","version","custody_generation","last_sequence","position","origin","destination","handoff_id");foreach(var key in new[]{"source","destination_owner","origin","destination","state"})Rules.Text(h[key]);foreach(var key in new[]{"owner","category","state","barcode"})Rules.Text(unit[key]);var id=Rules.Uuid(unit["id"]);var state=Rules.Text(h["state"]);var source=Rules.Text(h["source"]);var category=Rules.Text(unit["category"]);var raw=source=="logistics"&&category=="raw";
        if(state is not ("offered" or "departed" or "acknowledged")||e["type"]!.ToString()!="handling."+state+".v1"||e["source"]!.ToString()!=source||e["destination"]!.ToString()!="storage"||e["boundary"]!.ToString()!="supply"||(!raw&&source!="manufacturing")||h["destination_owner"]!.ToString()!="storage"||unit["owner"]!.ToString()!=source||(!raw&&category!="finished"))throw new Conflict("Unsupported finished receiving route");
        foreach(var key in new[]{"run_id","epoch"})if(!JsonNode.DeepEquals(h[key],e[key])||!JsonNode.DeepEquals(unit[key],h[key]))throw new Conflict("Inbound custody scope mismatch");if(!JsonNode.DeepEquals(h["id"],e["aggregate_id"])||!JsonNode.DeepEquals(h["id"],e["causation_id"])||!JsonNode.DeepEquals(unit["version"],e["aggregate_version"])||Rules.Text(unit["barcode"])!="HU-"+id.ToString("N").ToUpperInvariant())throw new Conflict("Inbound custody envelope identity mismatch");
        Endpoint(h["origin"],source,raw?"dock":"cell_output",category);Endpoint(h["destination"],"storage","dock",category);if(!Rules.Text(h["destination"]).StartsWith(raw?"storage.inbound.dock":"storage.finished_receipt.dock")||raw&&!Rules.Text(h["origin"]).StartsWith("logistics.inbound.dock"))throw new Conflict("Inbound units require a receiving dock");if(h["reason"] is not null)throw new Conflict("Positive custody proof cannot carry a rejection reason");
        if(unit["contents"] is not JsonArray contents||contents.Count!=1||contents[0] is not JsonObject item)throw new Validation("One complete SKU per native unit required");Complete(item,"sku","quantity");Rules.Text(item["sku"]);Rules.Integer(item["quantity"],1,10000);var version=Rules.Integer(unit["version"],1,int.MaxValue);var sequence=Rules.Integer(unit["last_sequence"],0,int.MaxValue);var generation=Rules.Integer(unit["custody_generation"],0,int.MaxValue);
        if(state=="offered"){
            if(version>int.MaxValue-2||sequence>int.MaxValue-2||generation>int.MaxValue-1||unit["state"]!.ToString()!="reserved"||!JsonNode.DeepEquals(unit["position"],h["origin"])||unit["origin"] is not null||unit["destination"] is not null||unit["handoff_id"] is not null||h["departure_token"] is not null||h["receipt_id"] is not null)throw new Conflict("Inbound offer requires placed reserved source unit with counter headroom");
        }else{
            var token=h["departure_token"] as JsonObject??throw new Validation("Inbound departure proof required");Complete(token,"id","handoff_id","unit_id","run_id","epoch","custody_generation","last_sequence","unit_version");Rules.Uuid(token["id"]);if(version==int.MaxValue||sequence<1||sequence==int.MaxValue||generation<1||!JsonNode.DeepEquals(token["handoff_id"],h["id"])||!JsonNode.DeepEquals(token["unit_id"],unit["id"])||!JsonNode.DeepEquals(token["unit_version"],unit["version"])||unit["state"]!.ToString()!="in_transit"||unit["position"] is not null||!JsonNode.DeepEquals(unit["origin"],h["origin"])||!JsonNode.DeepEquals(unit["destination"],h["destination"])||!JsonNode.DeepEquals(unit["handoff_id"],h["id"]))throw new Conflict("Inbound departure requires matching unplaced custody");foreach(var key in new[]{"run_id","epoch","last_sequence","custody_generation"})if(!JsonNode.DeepEquals(token[key],unit[key]))throw new Conflict("Inbound departure token scope or sequence changed");if(state=="acknowledged")Rules.Uuid(h["receipt_id"]);else if(h["receipt_id"] is not null)throw new Conflict("Departure cannot contain a receipt");
        }return h;
    }
    public static string Ingest(Ledger ledger,Settings settings,JsonObject e,string endpoint){Validate(e);if(settings.Providers["supply"]?.ToString()!="helics"||!settings.HasPeer("supply",Rules.Text(e["source"]),endpoint)||e["federation_id"]!.ToString()!=settings.Federation)throw new Conflict("Unconfigured finished custody peer");
        return ledger.Db.Transaction(u=>{var run=u.Run();if(Ledger.Id(run)!=Ledger.Id(e,"run_id")||Ledger.Id(run,"epoch")!=Ledger.Id(e,"epoch"))return "fenced";var old=u.Query("SELECT * FROM warehouse_custody_events WHERE event_id=@p0",Ledger.Id(e,"event_id")).FirstOrDefault();if(old is not null){if(!JsonNode.DeepEquals(old["envelope"],e))throw new Conflict("Inbound event identity changed");if(run["state"]!.ToString() is "running" or "held"){
            u.Exec("UPDATE jobs SET status='pending',due_at=@p0,retry_after=clock_timestamp(),error=NULL WHERE id=@p1 AND EXISTS(SELECT 1 FROM warehouse_commands WHERE id=@p1 AND retryable_capacity)",Math.Max(Ledger.Num(run,"granted"),Ledger.Num(e,"effective_time")),Ledger.Id(old,"command_id"));u.Exec("UPDATE warehouse_commands SET status='pending',error=NULL,retryable_capacity=false WHERE id=@p0 AND retryable_capacity",Ledger.Id(old,"command_id"));u.Exec("UPDATE outbox SET retry_after=clock_timestamp() WHERE job_id=@p0",Ledger.Id(old,"command_id"));Replay(u,run,e);}return "duplicate";}
            if(run["state"]!.ToString() is not ("running" or "held"))throw new Conflict("Inactive finished receiving run");var id=Guid.NewGuid();var due=Math.Max(Ledger.Num(run,"granted"),Ledger.Num(e,"effective_time"));u.Exec("INSERT INTO jobs(id,run_id,epoch,idempotency_key,due_at,original_due_at,payload) VALUES (@p0,@p1,@p2,@p3,@p4,@p5,@p6)",id,Ledger.Id(run),Ledger.Id(run,"epoch"),"boundary:"+Ledger.Id(e,"event_id"),due,Ledger.Num(e,"effective_time"),new JsonObject {["finished_custody"]=e.DeepClone(),["custody_endpoint"]=endpoint});u.Exec("INSERT INTO warehouse_commands(id,run_id,command) VALUES (@p0,@p1,@p2)",id,Ledger.Id(run),new JsonObject {["action"]="finished_custody",["handoff_id"]=e["aggregate_id"]!.DeepClone()});u.Exec("INSERT INTO warehouse_custody_events VALUES (@p0,@p1,@p2,@p3)",Ledger.Id(e,"event_id"),Ledger.Id(run),e,id);return "accepted";
        });
    }
    public static void Execute(Unit u,JsonObject run,Settings settings,JsonObject job){u.Exec("SAVEPOINT finished_custody_effect");try{Warehouse.Ensure(u,run);var result=Apply(u,run,settings,Ledger.Id(job),job["payload"]!["finished_custody"]!.AsObject());u.Exec("UPDATE warehouse_commands SET status='completed',result=@p0,error=NULL,retryable_capacity=false,completed_at=@p1 WHERE id=@p2",result,Ledger.Num(run,"granted"),Ledger.Id(job));}catch(Exception error)when(error is Conflict or Validation){u.Exec("ROLLBACK TO SAVEPOINT finished_custody_effect");if(error is not Capacity)CustodyQuarantine.Record(u,run,job["payload"]!["finished_custody"]!.AsObject(),job["payload"]?["custody_endpoint"]?.ToString()??"","apply",error.Message,Ledger.Id(job));u.Exec("UPDATE warehouse_commands SET status='rejected',error=@p0,retryable_capacity=@p1,completed_at=@p2 WHERE id=@p3",error.Message,error is Capacity,Ledger.Num(run,"granted"),Ledger.Id(job));}}
    static void Compatible(Unit u,JsonObject run,JsonObject h,string logical){var sku=h["unit"]!["contents"]![0]!["sku"]!.ToString();if(u.Query("SELECT 1 FROM warehouse_catalog c JOIN warehouse_stock s USING(run_id,sku) WHERE c.run_id=@p0 AND c.sku=@p1 AND c.kind=@p3 AND s.location=@p2",Ledger.Id(run),sku,logical,Rules.Text(h["unit"]!["category"])).Count==0)throw new Conflict("Unknown finished SKU or receiving location");}
    static JsonObject Apply(Unit u,JsonObject run,Settings settings,Guid command,JsonObject e){var h=Validate(e);var unit=h["unit"]!.AsObject();var id=Ledger.Id(h);var old=u.Query("SELECT * FROM warehouse_custody_receivers WHERE id=@p0",id).FirstOrDefault();if(old is not null&&Ledger.Id(old,"correlation_id")!=Ledger.Id(e,"correlation_id"))throw new Conflict("Inbound custody correlation changed");
        if(h["state"]!.ToString()=="offered"){
            if(old is not null){if(!JsonNode.DeepEquals(old["offer"],h))throw new Conflict("Inbound handoff identity changed");return h;}
            var logical=unit["category"]!.ToString()=="raw"?Settings.Env("STORAGE_RAW_LOCATION","RAW-A"):Settings.Env("STORAGE_FINISHED_LOCATION","FINISHED-A");Compatible(u,run,h,logical);if(u.Query("SELECT 1 FROM warehouse_handling_units WHERE id=@p0 UNION ALL SELECT 1 FROM warehouse_custody_receivers WHERE unit_id=@p0 AND state='accepted'",Ledger.Id(unit)).Count>0)throw new Conflict("Inbound barcode is already known or accepted");
            if(u.Query("SELECT 1 FROM warehouse_handling_units WHERE run_id=@p0 AND epoch=@p1 AND (position=@p2 OR (state='in_transit' AND destination=@p2)) UNION ALL SELECT 1 FROM warehouse_custody_receivers WHERE run_id=@p0 AND epoch=@p1 AND destination=@p2 AND state='accepted'",Ledger.Id(run),Ledger.Id(run,"epoch"),Rules.Text(h["destination"])).Count>0)throw new Capacity("Inbound receiving dock unavailable; retry identical offer after capacity frees");
            try{Warehouse.Capacity(u,Ledger.Id(run),logical,unit["contents"]![0]!["quantity"]!.GetValue<int>());}catch(Conflict error){throw new Capacity(error.Message);}
            var accepted=(JsonObject)h.DeepClone();accepted["state"]="accepted";u.Exec("INSERT INTO warehouse_custody_receivers VALUES (@p0,@p1,@p2,@p3,@p4,@p5,@p6,@p7,'accepted',@p8,@p9,NULL,@p10)",id,Ledger.Id(run),Ledger.Id(run,"epoch"),Ledger.Id(unit),Rules.Text(h["destination"]),logical,Ledger.Id(e,"correlation_id"),unit["contents"]![0]!["quantity"]!.GetValue<int>(),h,accepted,command);Publish(u,run,settings,accepted,Ledger.Id(e,"correlation_id"));return accepted;
        }
        if(old is null)throw new Conflict("Inbound departure requires durable dock acceptance");var offer=old["offer"]!.AsObject();foreach(var key in new[]{"id","run_id","epoch","source","destination_owner","origin","destination"})if(!JsonNode.DeepEquals(h[key],offer[key]))throw new Conflict("Inbound departure changed accepted custody");var expected=(JsonObject)offer["unit"]!.DeepClone();expected["state"]="in_transit";expected["position"]=null;expected["origin"]=h["origin"]!.DeepClone();expected["destination"]=h["destination"]!.DeepClone();expected["handoff_id"]=h["id"]!.DeepClone();foreach(var key in new[]{"version","last_sequence","custody_generation"})expected[key]=expected[key]!.GetValue<int>()+1;if(!JsonNode.DeepEquals(expected,unit))throw new Conflict("Inbound departure changed contents or skipped a custody sequence");
        if(old["receipt"] is JsonObject receipt){var check=(JsonObject)h.DeepClone();check["state"]="received";check["receipt_id"]=receipt["receipt_id"]!.DeepClone();if(!JsonNode.DeepEquals(check,receipt)||h["state"]!.ToString()=="acknowledged"&&!JsonNode.DeepEquals(h["receipt_id"],receipt["receipt_id"]))throw new Conflict("Inbound receipt proof changed");if(h["state"]!.ToString()=="acknowledged")u.Exec("UPDATE warehouse_custody_receivers SET state='acknowledged' WHERE id=@p0",id);return receipt;}
        if(h["state"]!.ToString()!="departed")throw new Conflict("Inbound acknowledgement preceded receipt");var location=Rules.Text(old["logical_location"]);Compatible(u,run,h,location);var item=unit["contents"]![0]!.AsObject();var quantity=item["quantity"]!.GetValue<int>();Warehouse.Capacity(u,Ledger.Id(run),location,quantity,id);
        var manifest=new JsonArray(new JsonObject {["id"]=unit["id"]!.DeepClone(),["quantity"]=quantity});var record=u.One("INSERT INTO warehouse_receipts(id,run_id,sku,location,quantity,correlation_id,status,unit_manifest,version) VALUES (@p0,@p1,@p2,@p3,@p4,@p5,'received',@p6,2) RETURNING *",command,Ledger.Id(run),Rules.Text(item["sku"]),location,quantity,Ledger.Id(e,"correlation_id"),manifest);
        u.Exec("INSERT INTO warehouse_handling_units(id,barcode,run_id,epoch,sku,quantity,category,state,logical_location,position,receipt_id,correlation_id,version,custody_generation,last_sequence) VALUES (@p0,@p1,@p2,@p3,@p4,@p5,@p13,'available',@p6,@p7,@p8,@p9,@p10,@p11,@p12)",Ledger.Id(unit),Rules.Text(unit["barcode"]),Ledger.Id(run),Ledger.Id(run,"epoch"),Rules.Text(item["sku"]),quantity,location,Rules.Text(h["destination"]),command,Ledger.Id(e,"correlation_id"),unit["version"]!.GetValue<int>(),unit["custody_generation"]!.GetValue<int>(),unit["last_sequence"]!.GetValue<int>(),Rules.Text(unit["category"]));
        HandlingUnits.Movement(u,run,command,unit,"receive",Rules.Text(h["origin"]),Rules.Text(h["destination"]),Ledger.Id(e,"correlation_id"));Warehouse.Move(u,run,command,"receive",record,quantity,0);Warehouse.PublishOutcome(u,run,command,"receive",record);var received=(JsonObject)h.DeepClone();received["state"]="received";received["receipt_id"]=Rules.Uuid5(id,"storage-receipt").ToString();u.Exec("UPDATE warehouse_custody_receivers SET state='received',receipt=@p0 WHERE id=@p1",received,id);Publish(u,run,settings,received,Ledger.Id(e,"correlation_id"));return received;
    }
    static void Publish(Unit u,JsonObject run,Settings settings,JsonObject h,Guid correlation){var id=Rules.Uuid5(Ledger.Id(h),"storage:"+h["state"]!.ToString());var e=new JsonObject {["schema_version"]="1.0",["type"]="handling."+h["state"]!.ToString()+".v1",["event_id"]=id.ToString(),["federation_id"]=settings.Federation,["run_id"]=run["id"]!.DeepClone(),["epoch"]=run["epoch"]!.DeepClone(),["correlation_id"]=correlation.ToString(),["causation_id"]=h["id"]!.DeepClone(),["aggregate_id"]=h["id"]!.DeepClone(),["aggregate_version"]=h["unit"]!["version"]!.DeepClone(),["source"]="storage",["destination"]=h["source"]!.DeepClone(),["boundary"]=h["source"]!.ToString()=="logistics"?"destinations":"materials",["effective_time"]=Ledger.Num(run,"granted")+settings.Quantum,["wall_time"]=DateTimeOffset.UtcNow.ToString("O"),["quantity_unit"]="item",["payload"]=h.DeepClone()};u.Exec("INSERT INTO boundary_outbox(id,run_id,envelope) VALUES (@p0,@p1,@p2) ON CONFLICT(id) DO NOTHING",id,Ledger.Id(run),e);}
    public static JsonArray Snapshot(Unit u,JsonObject run)=>new(u.Query("SELECT * FROM warehouse_custody_receivers WHERE run_id=@p0 AND epoch=@p1 ORDER BY id",Ledger.Id(run),Ledger.Id(run,"epoch")).Select(row=>{var h=(JsonObject)(row["receipt"]??row["acceptance"])!.DeepClone();h["state"]=row["state"]!.DeepClone();return (JsonNode?)h;}).ToArray());
    public static void Recover(Unit u,JsonObject run){if(run["state"]!.ToString() is not ("running" or "held"))return;foreach(var row in u.Query("SELECT DISTINCT b.envelope FROM boundary_outbox b JOIN warehouse_custody_receivers h ON h.id::text=b.envelope->'payload'->>'id' AND h.state=b.envelope->'payload'->>'state' WHERE h.run_id=@p0 AND h.epoch=@p1 AND h.state IN ('accepted','received') AND b.run_id=@p0 AND NOT EXISTS(SELECT 1 FROM boundary_outbox n WHERE n.run_id=b.run_id AND n.envelope->>'event_id'=b.envelope->>'event_id' AND (n.sent_at IS NULL OR n.sent_at>clock_timestamp()-interval '5 seconds'))",Ledger.Id(run),Ledger.Id(run,"epoch")))u.Exec("INSERT INTO boundary_outbox(id,run_id,envelope) VALUES (@p0,@p1,@p2)",Guid.NewGuid(),Ledger.Id(run),row["envelope"]!);}
    static void Replay(Unit u,JsonObject run,JsonObject e){var stage=e["type"]!.ToString()=="handling.offered.v1"?"accepted":e["type"]!.ToString()=="handling.departed.v1"?"received":null;if(stage is null)return;var id=Rules.Uuid5(Ledger.Id(e,"aggregate_id"),"storage:"+stage);var old=u.Query("SELECT envelope FROM boundary_outbox b WHERE run_id=@p0 AND envelope->>'event_id'=@p1 AND NOT EXISTS(SELECT 1 FROM boundary_outbox n WHERE n.run_id=b.run_id AND n.envelope->>'event_id'=b.envelope->>'event_id' AND (n.sent_at IS NULL OR n.sent_at>clock_timestamp()-interval '5 seconds')) LIMIT 1",Ledger.Id(run),id.ToString()).FirstOrDefault();if(old is not null)u.Exec("INSERT INTO boundary_outbox(id,run_id,envelope) VALUES (@p0,@p1,@p2)",Guid.NewGuid(),Ledger.Id(run),old["envelope"]!);}
}
